function kahnTopologicalSort(graph):
    in_degree = {v: 0 for v in graph.vertices}
    for u in graph.vertices:
        for v in graph.adj[u]:
            in_degree[v] += 1

    queue = Queue()
    for u in graph.vertices:
        if in_degree[u] == 0:
            queue.put(u)

    result = []
    count_visited_nodes = 0

    while not queue.empty():
        u = queue.get()
        result.append(u)
        count_visited_nodes += 1

        for v in graph.adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.put(v)

    if count_visited_nodes != len(graph.vertices):
        // Graph has a cycle, topological sort not possible
        return [] // Or raise error
    else:
        return result
